import os
import asyncio
import json
from typing import Dict, Any, Optional
from datetime import datetime
import logging

from fastapi import FastAPI, HTTPException, WebSocket, WebSocketDisconnect
from fastapi.middleware.cors import CORSMiddleware
from fastapi.staticfiles import StaticFiles
from fastapi.responses import HTMLResponse
from pydantic import BaseModel
import uvicorn

# AI Integráció
from cerebras.cloud.sdk import Cerebras
from google import genai
from google.genai import types

# Logging beállítás
logging.basicConfig(level=logging.INFO)
logger = logging.getLogger(__name__)

# Pydantic modellek
class ChatMessage(BaseModel):
    message: str
    model: str = "gpt-oss-120b"
    conversation_id: Optional[str] = None

class ProteinPredictionRequest(BaseModel):
    sequence: str
    job_name: Optional[str] = None
    parameters: Optional[Dict[str, Any]] = {}

class JADEDPlatform:
    def __init__(self):
        self.app = FastAPI(
            title="JADED Platform",
            description="Advanced Multi-Language Protein Analysis Platform",
            version="3.0.0"
        )

        # AI kliensek inicializálása
        self.cerebras_client = Cerebras(
            api_key="csk-hpy3d9x35t8tjxeheh3kkx5rrfctte6m52rmdkxwh4kt5y2r"
        )

        self.gemini_client = genai.Client(
            api_key="AIzaSyDGk_gmTXUr_lL4YlwvzDmrzh49LKAetAs"
        )

        # WebSocket connections
        self.active_connections: Dict[str, WebSocket] = {}

        self._setup_middleware()
        self._setup_routes()

    def _setup_middleware(self):
        self.app.add_middleware(
            CORSMiddleware,
            allow_origins=["*"],
            allow_credentials=True,
            allow_methods=["*"],
            allow_headers=["*"],
        )

    def _setup_routes(self):
        @self.app.get("/")
        async def home():
            return HTMLResponse(content=open("static/index.html", "r", encoding="utf-8").read())

        @self.app.post("/api/chat")
        async def chat_endpoint(request: ChatMessage):
            try:
                if "gpt-oss" in request.model:
                    return await self._handle_cerebras_chat(request.message, request.model)
                elif "gemini" in request.model:
                    return await self._handle_gemini_chat(request.message, request.model)
                else:
                    return await self._handle_cerebras_chat(request.message, "gpt-oss-120b")
            except Exception as e:
                logger.error(f"Chat error: {str(e)}")
                raise HTTPException(status_code=500, detail=str(e))

        @self.app.post("/api/protein/predict")
        async def predict_protein(request: ProteinPredictionRequest):
            try:
                # AlphaFold predikció szimulálása
                job_id = f"job_{int(datetime.now().timestamp())}"

                # Valós implementációban itt hívnánk az AlphaFold szolgáltatást
                result = {
                    "job_id": job_id,
                    "status": "completed",
                    "sequence": request.sequence,
                    "structure_data": self._generate_mock_pdb(request.sequence),
                    "confidence_score": 0.85,
                    "processing_time": 45.2,
                    "timestamp": datetime.now().isoformat()
                }

                return result
            except Exception as e:
                logger.error(f"Protein prediction error: {str(e)}")
                raise HTTPException(status_code=500, detail=str(e))

        @self.app.websocket("/ws/{client_id}")
        async def websocket_endpoint(websocket: WebSocket, client_id: str):
            await websocket.accept()
            self.active_connections[client_id] = websocket
            try:
                while True:
                    data = await websocket.receive_text()
                    message_data = json.loads(data)

                    if message_data.get("type") == "chat":
                        response = await self._handle_websocket_chat(message_data)
                        await websocket.send_text(json.dumps(response))

            except WebSocketDisconnect:
                del self.active_connections[client_id]

        @self.app.get("/api/health")
        async def health_check():
            return {
                "status": "healthy",
                "timestamp": datetime.now().isoformat(),
                "services": {
                    "cerebras": True,
                    "gemini": True,
                    "alphafold": True
                }
            }

    async def _handle_cerebras_chat(self, message: str, model: str):
        try:
            stream = self.cerebras_client.chat.completions.create(
                messages=[{
                    "role": "user",
                    "content": message
                }],
                model=model,
                stream=True,
                max_completion_tokens=65536,
                temperature=0.23,
                top_p=0.05
            )

            response_text = ""
            for chunk in stream:
                if chunk.choices[0].delta.content:
                    response_text += chunk.choices.delta.content

            return {
                "response": response_text,
                "model": model,
                "provider": "cerebras",
                "timestamp": datetime.now().isoformat()
            }

        except Exception as e:
            logger.error(f"Cerebras API error: {str(e)}")
            raise HTTPException(status_code=500, detail=f"Cerebras error: {str(e)}")

    async def _handle_gemini_chat(self, message: str, model: str):
        try:
            contents = [
                types.Content(
                    role="user",
                    parts=[types.Part.from_text(text=message)]
                )
            ]

            config = types.GenerateContentConfig(
                thinking_config=types.ThinkingConfig(thinking_budget=-1)
            )

            response_text = ""
            for chunk in self.gemini_client.models.generate_content_stream(
                model="gemini-2.5-pro",
                contents=contents,
                config=config
            ):
                if chunk.text:
                    response_text += chunk.text

            return {
                "response": response_text,
                "model": model,
                "provider": "gemini",
                "timestamp": datetime.now().isoformat()
            }

        except Exception as e:
            logger.error(f"Gemini API error: {str(e)}")
            raise HTTPException(status_code=500, detail=f"Gemini error: {str(e)}")

    async def _handle_websocket_chat(self, message_data):
        message = message_data.get("message", "")
        model = message_data.get("model", "gpt-oss-120b")

        if "gpt-oss" in model:
            return await self._handle_cerebras_chat(message, model)
        else:
            return await self._handle_gemini_chat(message, model)

    def _generate_mock_pdb(self, sequence):
        # Mock PDB generálása demó célokra
        return f"""HEADER    JADED PLATFORM PREDICTION
REMARK   1 PREDICTED STRUCTURE FOR SEQUENCE: {sequence[:20]}...
ATOM      1  N   ALA A   1      20.154  25.000  30.000  1.00 85.00           N  
ATOM      2  CA  ALA A   1      21.500  25.000  30.500  1.00 85.00           C  
ATOM      3  C   ALA A   1      22.000  26.400  30.800  1.00 85.00           C  
ATOM      4  O   ALA A   1      21.500  27.400  30.300  1.00 85.00           O  
END
"""

# FastAPI app indítása
platform = JADEDPlatform()
app = platform.app

# Static fájlok
app.mount("/static", StaticFiles(directory="static"), name="static")

if __name__ == "__main__":
    uvicorn.run(app, host="0.0.0.0", port=8000)
```

